def copy_activity(source, sink):
    sink.extend(source)
    return {"activity": "Copy", "rows_copied": len(source)}

def transform_activity(rows):
    return [{"id": r["id"], "total": round(r["amount"] * 1.21, 2)} for r in rows]

raw_rows = [{"id": 1, "amount": 100.0}, {"id": 2, "amount": 50.0}]
staged = []
copy_result = copy_activity(raw_rows, staged)
transformed = transform_activity(staged)

pipeline_run = {
    "pipeline": "pl_ingest_orders",
    "activities": [copy_result, {"activity": "DataFlow", "rows_out": len(transformed)}],
}
print(pipeline_run)
for row in transformed:
    print(row)
